insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_dance2_v1'
from (values
('117.206.b.1.A',2,'Seventh-grade dancers mirror a partner''s slow arm sweeps while keeping a gap between them. They are practicing:','["spatial awareness in a pair", "lighting cues", "ticket sales", "set building"]'::jsonb,0,'Mirroring while keeping distance builds spatial awareness with others.','original'),
('117.206.b.1.A',2,'A dancer finishes a turn and can tell her hip is slightly out of line without looking. This sense is:','["pitch memory", "kinesthetic awareness", "color matching", "reading ability"]'::jsonb,1,'Kinesthetic awareness is feeling where body parts are.','original'),
('117.206.b.1.B',2,'Which choice shows wellness thinking before a dance rehearsal?','["skipping water", "ignoring soreness", "eating a balanced meal and staying hydrated", "sleeping little"]'::jsonb,2,'Wellness for dancers includes fuel, water and rest.','original'),
('117.206.b.1.B',3,'Managing stress through breathing before a recital is part of dancer:','["ticket pricing", "stage design", "costume care", "mental wellness"]'::jsonb,3,'Wellness includes mental and emotional health.','original'),
('117.206.b.1.C',3,'A dancer shows she understands body science when she explains why bending the knees on landing:','["absorbs the force of a jump", "makes the music louder", "changes the costume", "adds more props"]'::jsonb,0,'Soft knees protect joints.','original'),
('117.206.b.1.C',3,'Demonstrating the ballet term ''tendu'' means stretching the foot:','["off the stage", "along the floor until the toes point", "behind the neck", "above the head"]'::jsonb,1,'A tendu is a stretch of the leg and foot along the floor.','original'),
('117.206.b.1.D',3,'A dancer moves in a zigzag path across the room, then curls into a low shape. She is exploring the element of:','["costume", "tempo only", "space", "rhyme"]'::jsonb,2,'Pathways and levels are parts of space.','original'),
('117.206.b.1.D',3,'Sharp, sudden movements versus smooth, flowing movements show different qualities of:','["timing only", "spacing", "lighting", "energy"]'::jsonb,3,'Energy includes qualities such as sharp, smooth, swinging.','original'),
('117.206.b.2.A',2,'A dancer who keeps ribs stacked over the hips during a balance is practicing proper:','["body alignment", "stage lighting", "music tempo", "costume fitting"]'::jsonb,0,'Alignment stacks body parts for stability and safety.','original'),
('117.206.b.2.A',3,'Poor alignment while landing jumps most often leads to:','["longer rehearsal", "strain on knees and ankles", "louder music", "better balance"]'::jsonb,1,'Misaligned landings stress joints.','original'),
('117.206.b.2.B',3,'A student creates a short phrase, repeats it in a new level, then adds a turn. She is using which choreographic idea?','["a rule of rhyme", "a hidden script", "variation of a phrase", "a costume change"]'::jsonb,2,'Choreographers vary phrases through level, direction and tempo.','original'),
('117.206.b.2.B',3,'When a group improvises with a prompt such as ''moving through thick fog,'' the dancers are:','["memorizing a routine", "ordering costumes", "painting a set", "exploring movement choices on the spot"]'::jsonb,3,'Improvisation explores spontaneous movement.','original'),
('117.206.b.2.C',3,'Which movement study uses a steady 4-count pulse while traveling forward, backward and sideways?','["one combining rhythm and spatial directions", "one with no counts", "one done sitting still", "one with only a pose"]'::jsonb,0,'Rhythm plus direction defines these studies.','original'),
('117.206.b.2.C',3,'To distinguish two movement studies, a student compares their:','["costume colors", "rhythms and floor patterns", "font sizes", "ticket prices"]'::jsonb,1,'Rhythm and spatial patterns separate movement studies.','original'),
('117.206.b.2.D',2,'Wide, open arms and a lifted chest can help a dancer express:','["the time of day", "a bus delay", "happiness or pride", "boredom with homework"]'::jsonb,2,'Posture and gesture communicate emotion.','original'),
('117.206.b.2.D',3,'A group dance shows teamwork by having everyone lift and pass a prop. The dancers are expressing the idea of:','["isolation", "delay", "silence", "cooperation"]'::jsonb,3,'Group movement can express ideas such as cooperation.','original'),
('117.206.b.3.A',2,'A style known for lyrical leaps, isolations and syncopated rhythm, often set to popular music, is:','["jazz dance", "folk song", "waltz only", "opera"]'::jsonb,0,'Jazz dance uses isolations and syncopation.','original'),
('117.206.b.3.A',3,'A student demonstrates a ballet style by performing:','["stomping with metal plates only", "controlled turned-out movements with graceful lines", "random walking", "freeform rolling only"]'::jsonb,1,'Ballet features turnout and lines.','original'),
('117.206.b.3.B',3,'To project to an audience, a dancer uses:','["whispers", "small shuffles only", "clear focus and full, energized movement", "hidden gestures"]'::jsonb,2,'Projection means communicating outward.','original'),
('117.206.b.3.B',3,'During a solo, a dancer wants the back row to see her expression. She should:','["look at her feet", "turn from the crowd", "shrink her movements", "lift her gaze and extend her movement outward"]'::jsonb,3,'Projection involves focus and extension.','original'),
('117.206.b.3.C',3,'A class records its performance and watches the playback to adjust formations. This is using technology in:','["dance practice", "a math quiz", "a bus route", "a bake sale"]'::jsonb,0,'Video review supports practice.','original'),
('117.206.b.3.C',3,'Choosing a lighting color to match the mood of a dance is an example of using:','["a locker combo", "technology in performance", "pencil and paper", "a hallway pass"]'::jsonb,1,'Stage lighting is a performance technology.','original'),
('117.206.b.3.D',2,'A cool-down helps the body by:','["starting a new routine", "building speed", "slowing the heart rate and easing muscles", "adding weights"]'::jsonb,2,'Cool-downs help the body recover.','original'),
('117.206.b.3.D',3,'An effective warm-up usually starts with:','["a full-speed jump", "a long hold of a tough pose", "a deep split", "gentle movement that raises body temperature"]'::jsonb,3,'Warm up gradually before stretching hard.','original'),
('117.206.b.4.A',3,'Recognizing that a ceremonial dance is tied to a community''s history helps a student see its:','["cultural significance", "costume fabric", "stage size", "ticket cost"]'::jsonb,0,'Dances can carry history and meaning.','original'),
('117.206.b.4.A',3,'Which would a student study to understand when a dance form developed?','["the number of dancers only", "its historical period and origin", "the rehearsal room color", "the brand of the shoes"]'::jsonb,1,'Historical context explains origins.','original'),
('117.206.b.4.B',3,'To interpret a historical dance form, a student looks closely at its:','["bus schedule", "parking map", "characteristic steps, patterns and music", "price list"]'::jsonb,2,'Interpretation looks at the movement features of a form.','original'),
('117.206.b.4.B',4,'Learning who developed a dance style lets students recognize the contributions of:','["random strangers", "the audience''s seat numbers", "the building''s builders", "its founding performers and choreographers"]'::jsonb,3,'Contributions are tied to artists.','original'),
('117.206.b.4.C',2,'A student recognizes a dance as part of her heritage when it comes from:','["her family''s culture", "a lunch menu", "a random game", "a gym rule"]'::jsonb,0,'Heritage dances come from one''s background.','original'),
('117.206.b.4.C',2,'A dance about a town''s river and farms reflects the dancers'':','["transcript", "environment", "allowance", "password"]'::jsonb,1,'Environment-based dances reflect place.','original'),
('117.206.b.4.D',3,'A student who watches a filmed dance and then writes about how camera angles affect the dancers is evaluating dance in:','["a closet", "a dictionary", "media", "a garden"]'::jsonb,2,'Dance in film and video can be evaluated.','original'),
('117.206.b.4.D',3,'A class dances a scene about the water cycle for science. They are connecting dance to:','["a rest period", "a hall pass", "a grocery list", "another content area"]'::jsonb,3,'Dance can illustrate other subjects.','original'),
('117.206.b.5.A',3,'A student demonstrates performance quality by using precise timing, strong focus and:','["clean, controlled technique", "messy transitions", "random pauses", "hidden faces"]'::jsonb,0,'Quality shows in technique, timing and focus.','original'),
('117.206.b.5.A',3,'A dancer''s effectiveness is judged by how well she:','["arrives earliest", "communicates the intent of the dance", "wears the newest shoes", "sits closest"]'::jsonb,1,'Effectiveness is communicating meaning.','original'),
('117.206.b.5.B',3,'Describing how rhythmic counts and sequences in a dance relate to number patterns interprets the link between dance and:','["geography", "woodworking", "mathematics", "plumbing"]'::jsonb,2,'Counting and patterns relate to math.','original'),
('117.206.b.5.B',3,'Showing how a historical event inspired a movement piece connects dance to:','["a ruler", "a spelling list", "a lunch card", "social studies"]'::jsonb,3,'Dance can reflect history.','original'),
('117.206.b.5.C',3,'A student reproduces a short phrase from a famous American choreographer to study its:','["content and structure", "weight", "font size", "price"]'::jsonb,0,'Studying phrases reveals content and structure.','original'),
('117.206.b.5.C',3,'Demonstrating choreographic structure means showing how a dance is:','["advertised", "organized from beginning to end", "insured", "priced"]'::jsonb,1,'Structure is how a dance is organized.','original'),
('117.206.b.5.D',3,'After watching a video of her solo, a student explains which choices worked and what she would change. She is evaluating her:','["bus pass", "homework planner", "artistic decisions", "dress code"]'::jsonb,2,'Evaluation reflects on artistic choices.','original'),
('117.206.b.5.D',4,'Interpreting why you chose a fast tempo for a nervous mood in a personal dance work means explaining the:','["price of the tickets", "date of the recital", "size of the stage", "meaning behind a creative choice"]'::jsonb,3,'Interpretation explains the why behind choices.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
